    return (x + y - 1) / y
}

fun gcd(x: Long, y: Long): Long {
    if (x == 0L || y == 0L) return x + y
    if (x > y) return gcd(x % y, y)
    return gcd(y % x, x)
}

fun end() {
    out.flush()
    System.exit(0)
}

fun printIntArray(a: IntArray) {
    for (x in a) print("$x ")
    print("\n")
}

fun printIntArrayList(a: ArrayList<Int>) {
    for (x in a) print("$x ")
    print("\n")
}

fun nextInt() = next().toInt()
fun nextLong() = next().toLong()
fun nextDouble() = next().toDouble()

val reader = BufferedReader(InputStreamReader(System.`in`))
val out = PrintWriter(System.out, false)
var tokenizer = StringTokenizer("")

fun println(o: Any) = out.println(o)
fun print(o: Any) = out.print(o)

fun next(): String {
    while (!tokenizer.hasMoreTokens())
        tokenizer = StringTokenizer(reader.readLine())
    return tokenizer.nextToken()
}

fun increase(map: HashMap<Int, Int>, k: Int) {
    map[k] = 1 + if (map.containsKey(k)) map[k]!! else 0
}

fun decrease(map: HashMap<Int, Int>, k: Int) {
    map[k] = -1 + if (map.containsKey(k)) map[k]!! else 0
}
